#include "../core/material_prepare.h"
#include <iostream>
using namespace P4MapKit;
using namespace P4MapKit::Material;
namespace C=P4MapKit::CustomMaterial;
static int checks=0;
static void Check(bool good,const char* name){++checks;if(!good)throw std::runtime_error(name);}
template<class F>static void Refuses(F action,const char* category){bool hit=false;try{action();}catch(const Refused& e){hit=e.name==category;}Check(hit,"named original preparation refusal");}
static void Put(C::Bytes& data,std::size_t at,std::uint64_t value,std::size_t width=4){for(std::size_t k=0;k<width;++k)data.at(at+k)=std::uint8_t(value>>(8*k));}
static C::Bytes Payload(const C::ShaderBindings& header,const std::string& text){auto payload=C::ShaderHeader(header);C::U32(payload,16);payload.resize(payload.size()+16);C::Bytes control(0x878+text.size()+1,0);Put(control,20,0x878);Put(control,24,text.size()+1);std::copy(text.begin(),text.end(),control.begin()+0x878);C::U32(payload,unsigned(control.size()));C::Append(payload,control);C::U32(payload,0);C::U32(payload,0xffffffff);C::U32(payload,0);C::U32(payload,0);C::U32(payload,0);C::U32(payload,4);return payload;}
int main(){try{
    const auto lines=MaterialInstructionLines("!!NVfp5.0\nOPTION NV_internal;\nTEMP R0;\n  MOV.F result_color0, {0}.x;;;\nEND\n");Check(lines==std::vector<std::string>{"MOV.F result_color0, {0}.x"},"exact declaration and semicolon removal");
    Refuses([&]{MaterialInstructionLines("MOV.F R0, {TEX:A}\n");},"material program unresolved");Refuses([&]{MaterialInstructionLines("END\n");},"material program empty");Refuses([&]{MaterialInstructionLines(std::string("MOV ")+char(0xff));},"material program text");
    FMaterialShaderMapEnvelope map;map.Frozen.resize(200,0);map.ShaderTypes={0x1234};Put(map.Frozen,176,1,8);Put(map.Frozen,192,3);Put(map.Frozen,196,0);FMaterialUniformTexture texture;texture.Parameter.Name="Albedo";map.Uniforms.Textures={texture};FMaterialShaderReference ref;ref.TypeHash=0x1234;ref.Frequency=3;ref.ResourceIndex=0;ref.NamedBuffers={{1,"Material"}};ref.UniformBufferHashes={{0,0xf10cd51552e37c76ull},{1,0x464d5173dc80b663ull}};
    C::ShaderBindings header;header.uniform_buffers.resize(2);header.inputs={{"in_texcoord0_centroid",2}};header.textures=C::BuildResourceTable({{1,{{0,3}}}},2);header.samplers=C::BuildResourceTable({{0,{{0,4}}},{1,{{1,2}}}},2);auto payload=Payload(header,"MOV.F result_color0, {0}.x;\nEND\n");auto prepared=PrepareOriginalMaterialPixelProgram(map,ref,payload,3);Check(prepared.Lines==std::vector<std::string>{"MOV.F result_color0, {0}.x"},"original embedded text becomes native instruction stream");Check(prepared.BaseBinding.TextureParameters.at(3)=="Albedo"&&prepared.BaseBinding.TextureEntries.at(3)==0&&prepared.SamplerParameters.at(2)=="Albedo"&&prepared.BaseBinding.ViewSamplers.at(4)==0,"typed material and View resource binding association");Check(prepared.BaseBinding.Varyings.at("in_texcoord0")==2&&!prepared.FactoryInputsProved&&!prepared.FamilyComplete&&!prepared.CompilerProven,"structural preparation preserves explicit input and proof scope");
    Refuses([&]{PrepareOriginalMaterialPixelProgram(map,ref,payload,0);},"material program archive association");auto invalidRef=ref;invalidRef.ResourceIndex=1;Refuses([&]{PrepareOriginalMaterialPixelProgram(map,invalidRef,payload,3);},"material shader reference");
    const auto controlAt=C::ShaderHeader(header).size()+4+16+4;auto invalidOffset=payload;Put(invalidOffset,controlAt+20,0xffffffff);Refuses([&]{PrepareOriginalMaterialPixelProgram(map,ref,invalidOffset,3);},"material program control");auto invalidSize=payload;Put(invalidSize,controlAt+24,0xffffffff);Refuses([&]{PrepareOriginalMaterialPixelProgram(map,ref,invalidSize,3);},"material program control");auto badUtf8=payload;badUtf8[controlAt+0x878]=0xff;Refuses([&]{PrepareOriginalMaterialPixelProgram(map,ref,badUtf8,3);},"material program text");auto truncated=payload;truncated.pop_back();Refuses([&]{PrepareOriginalMaterialPixelProgram(map,ref,truncated,3);},"material program payload");
    std::cout<<"native original material preparation checks="<<checks<<"\n";
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
